import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import f_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using stratified analysis
    strata = list(set(feats.stratum))
    if len(strata) == 1:
        strata = ['all']

    # Check for strong associations with outcome
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('clinical', 'derived'):
            # For clinical/derived variables, check if they're associated with outcome
            x = feats.x[:, i]
            y = feats.y
            t_stat, p_val = stats.ttest_ind(x[y==1], x[y==0])
            if abs(t_stat) > 2.0 and p_val < 0.05:
                effects.append((fid, abs(t_stat)))

    # Sort by effect size
    effects.sort(key=lambda x: x[1], reverse=True)

    # If we have a strong clinical driver, use it
    if effects and effects[0][1] > 2.5:
        driver = effects[0][0]
        # Find correlated features to include in model
        correlations = []
        driver_idx = feats.column(driver)
        driver_vals = feats.x[:, driver_idx]

        for i, fid in enumerate(feats.ids):
            if i != driver_idx:
                corr = np.corrcoef(driver_vals, feats.x[:, i])[0,1]
                if abs(corr) > 0.6:
                    correlations.append((fid, abs(corr)))

        correlations.sort(key=lambda x: x[1], reverse=True)

        # Include top correlated features and their products
        columns = [driver] + [fid for fid, _ in correlations[:5]]
        products = []

        # Add some interaction terms
        for i, fid1 in enumerate(columns):
            for j, fid2 in enumerate(columns[i+1:]):
                products.append((fid1, fid2))

        return Design(
            drivers=(driver,),
            columns=tuple(columns),
            products=tuple(products[:3]),
            loadings={driver: 1.0}
        )

    # Otherwise, look for direct predictors
    # Use ANOVA F-scores to rank features
    f_scores, p_values = f_classif(feats.x, feats.y)
    ranked_features = sorted(enumerate(f_scores), key=lambda x: x[1], reverse=True)

    # Select top features with significant p-values
    candidates = []
    for idx, score in ranked_features:
        if p_values[idx] < 0.05:
            candidates.append(feats.ids[idx])

    # Remove near-duplicates
    unique_candidates = []
    seen = set()

    for fid in candidates:
        if fid in seen:
            continue

        # Check if this feature is highly correlated with any already selected
        is_duplicate = False
        for existing_fid in unique_candidates:
            try:
                idx1 = feats.column(fid)
                idx2 = feats.column(existing_fid)
                corr = np.corrcoef(feats.x[:, idx1], feats.x[:, idx2])[0,1]
                if abs(corr) > 0.8:
                    is_duplicate = True
                    break
            except:
                pass

        if not is_duplicate:
            unique_candidates.append(fid)
            seen.add(fid)

        if len(unique_candidates) >= MAX_DRIVERS:
            break

    if not unique_candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build model with top features
    columns = unique_candidates[:MAX_DRIVERS]

    # Add some interaction terms
    products = []
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:]):
            products.append((fid1, fid2))

    # Simple loading weights (equal for now)
    loadings = {fid: 1.0 for fid in columns}

    # Try to identify a primary driver based on strongest effect
    drivers = ()
    if len(columns) > 0:
        # Look for features with highest effect sizes
        effect_sizes = []
        for i, fid in enumerate(columns):
            if feats.types[i] in ('expression', 'copy_number'):
                x = feats.x[:, feats.column(fid)]
                diff = np.mean(x[feats.y==1]) - np.mean(x[feats.y==0])
                effect_sizes.append((fid, abs(diff)))

        if effect_sizes:
            effect_sizes.sort(key=lambda x: x[1], reverse=True)
            drivers = (effect_sizes[0][0],)

    return Design(
        drivers=drivers,
        columns=tuple(columns),
        products=tuple(products[:3]),
        loadings=loadings
    )

